// Core navigation, storage and shared UI helpers used by card.js and document.js.

const Store = {
  KEY: 'scanner_recent_v1',
  list() {
    try { return JSON.parse(localStorage.getItem(this.KEY)) || []; }
    catch { return []; }
  },
  add(entry) {
    const list = this.list();
    list.unshift({ ...entry, ts: Date.now() });
    localStorage.setItem(this.KEY, JSON.stringify(list.slice(0, 20)));
    renderRecent();
  }
};

function showView(id) {
  document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
  document.getElementById(id).classList.add('active');
  window.scrollTo(0, 0);
}

function goHome() {
  if (window.CardScanner) window.CardScanner.reset();
  if (window.DocScanner) window.DocScanner.reset();
  showView('view-home');
}

function showOverlay(message) {
  const ov = document.getElementById('overlay');
  document.getElementById('overlay-text').textContent = message || 'Working…';
  ov.classList.add('show');
}
function hideOverlay() {
  document.getElementById('overlay').classList.remove('show');
}

let toastTimer;
function toast(message) {
  const el = document.getElementById('toast');
  el.textContent = message;
  el.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.remove('show'), 2400);
}

function timeAgo(ts) {
  const s = Math.floor((Date.now() - ts) / 1000);
  if (s < 60) return 'just now';
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  const d = Math.floor(h / 24);
  return `${d}d ago`;
}

function renderRecent() {
  const list = Store.list();
  const wrap = document.getElementById('recent-list');
  if (!list.length) {
    wrap.innerHTML = '<p class="empty-hint">Nothing scanned yet — your recent cards and documents will show up here.</p>';
    return;
  }
  wrap.innerHTML = list.map(item => `
    <div class="recent-item">
      <span class="ri-icon">${item.type === 'card' ? '👤' : '📄'}</span>
      <div class="ri-main">
        <div class="ri-title">${escapeHtml(item.title || 'Untitled')}</div>
        <div class="ri-sub">${item.type === 'card' ? 'Business card' : 'Document'} · ${timeAgo(item.ts)}</div>
      </div>
    </div>
  `).join('');
}

function escapeHtml(str) {
  return String(str || '').replace(/[&<>"']/g, c => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[c]));
}

document.addEventListener('DOMContentLoaded', () => {
  renderRecent();

  document.getElementById('btn-mode-card').addEventListener('click', () => {
    showView('view-card');
    window.CardScanner.start();
  });
  document.getElementById('btn-mode-doc').addEventListener('click', () => {
    showView('view-doc');
    window.DocScanner.start();
  });
  document.querySelectorAll('[data-nav-home]').forEach(btn => {
    btn.addEventListener('click', goHome);
  });

  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.register('sw.js').catch(() => {});
  }
});
